package br.com.admeclesial.infrastructure.configuration;
import br.com.admeclesial.infrastructure.persistence.usuario.*; import org.springframework.security.core.userdetails.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdmEclesialUserDetailsService implements UserDetailsService { private final UsuarioRepository usuarios; private final UsuarioPerfilRepository perfis; public AdmEclesialUserDetailsService(UsuarioRepository u,UsuarioPerfilRepository p){usuarios=u;perfis=p;} @Override @Transactional(readOnly=true) public UserDetails loadUserByUsername(String login){ var u=usuarios.findByLoginIgnoreCase(login).orElseThrow(()->new UsernameNotFoundException("Usuário não encontrado")); var authorities=perfis.findByUsuarioId(u.getId()).stream().map(p->new SimpleGrantedAuthority("ROLE_"+p.getPerfil().name())).toList(); return User.withUsername(u.getLogin()).password(u.getSenhaHash()).disabled(!u.isAtivo()).authorities(authorities).build(); } }
